p21.css:
$DOC { font-family: "Noto Sans JP", system-ui, sans-serif; font-size:9.5pt; line-height:1.62; color:#0f172a; padding:4mm 14mm 14mm; box-sizing:border-box; }
$DOC .submission-title{
          margin: 0 0 8mm; padding-bottom: 5mm;
          border-bottom: 1.5px solid #334155;
          color: #111827; font-size: 20pt; font-weight: 700;
          letter-spacing: 0.08em; text-align: center;
        }
$DOC .md-body h2{
          font-size: 13.5pt; font-weight: 700; margin: 6mm 0 3mm; padding: 2mm 4mm;
          color: #f8fafc; background: #0a1628; letter-spacing: 0.02em;
          break-inside: avoid; page-break-inside: avoid;
          -webkit-print-color-adjust: exact; print-color-adjust: exact;
        }

$DOC .md-body h3{
          font-size: 12pt; font-weight: 700; margin: 5mm 0 2mm; padding-bottom: 1mm;
          color: #0a1628; border-bottom: 2px solid #0a1628;
          break-inside: avoid; page-break-inside: avoid;
        }
$DOC .md-body h4{
          font-size: 10.5pt; font-weight: 700; margin: 3.5mm 0 1.5mm; padding-left: 2.5mm;
          color: #334155; border-left: 3px solid #94a3b8;
          break-inside: avoid; page-break-inside: avoid;
        }
$DOC .md-body p{ margin: 0 0 2mm; }
$DOC .md-body li{ margin: 0 0 0.6mm 6mm; position: relative; list-style: none; }
$DOC .md-body li::before{ content: '·'; position: absolute; left: -3mm; color: #0a1628; font-weight: 700; }
$DOC .md-body blockquote{ border-left: 2px solid #94a3b8; padding-left: 4mm; margin: 2mm 0; color: #475569; font-style: italic; }
$DOC .md-table-wrap{ margin: 3mm 0 5mm; overflow: hidden; }
$DOC .md-table{ width: 100%; border-collapse: collapse; table-layout: fixed; font-size: 9pt; line-height: 1.55; }
$DOC .md-table th, $DOC .md-table td{ border: 1px solid #cbd5e1; padding: 2mm 2.5mm; vertical-align: top; overflow-wrap: anywhere; }
$DOC .md-table th{ background: #e2e8f0; color: #0a1628; font-weight: 700; text-align: left; -webkit-print-color-adjust: exact; print-color-adjust: exact; }
$DOC .md-table tr{ break-inside: avoid; page-break-inside: avoid; }
$DOC .md-table th:first-child, $DOC .md-table td:first-child{ width: 12%; white-space: nowrap; }
$DOC .md-body h2{
          margin: 6mm 0 3mm; padding: 2.2mm 3mm;
          border-left: 4px solid #334155; background: #eef0f2;
          color: #111827; font-size: 13pt; font-weight: 600;
          font-family: "Hiragino Sans", "Hiragino Kaku Gothic ProN", "Yu Gothic", "Meiryo", sans-serif;
          break-after: avoid; page-break-after: avoid;
        }
$DOC .md-body h3{
          margin: 5mm 0 2mm; padding: 0 0 1.2mm;
          border-bottom: 1.5px solid #64748b;
          color: #1f2937; font-size: 11.5pt; font-weight: 700;
        }
$DOC .md-body h4{
          margin: 3.5mm 0 1.5mm; padding-left: 0;
          border-left: 0; color: #374151; font-size: 10.5pt;
        }
$DOC .md-body p{ margin: 0 0 2.2mm; }
$DOC .md-table-wrap{ margin: 2.5mm 0 4mm; overflow: visible; }
$DOC .md-table{ font-size: 8.4pt; line-height: 1.45; table-layout: auto; }
$DOC .md-table th, $DOC .md-table td{ border-color: #9ca3af; padding: 1.5mm 2mm; }
$DOC .md-table th{ background: #f3f4f6; color: #111827; text-align: center; }
$DOC .md-table th:first-child, $DOC .md-table td:first-child{ width: auto; white-space: normal; }

$DOC .report-editable-block {position:relative; min-width:0;}
$DOC { -webkit-box-decoration-break:clone; box-decoration-break:clone; }

